const prio = [/^cow$/i, /^duck$/i, /^chicken$/i, /^farmer$/i, /^goblin$/i];
const waypoints = [[3254,3258],[3202,3253]];
let wi = 0;
const hit = [];
const att = st => (st.nearbyNpcs||[]).filter(n=>n.optionsWithIndex&&n.optionsWithIndex.some(o=>/attack/i.test(o.text)));
while (Date.now() < end) {
  let st;
  try { st = sdk.getState(); } catch(e){ continue; }
  if (!st || !st.player) { await sdk.waitForTicks(1); continue; }
  if (st.dialog && st.dialog.isOpen) { try { await bot.dismissBlockingUI(); } catch(e){} }
  const list = att(st);
  let target = null;
  for (const p of prio) { const c = list.filter(n=>p.test(n.name)).sort((a,b)=>a.distance-b.distance); if (c.length) { target=c[0]; break; } }
