    try { const r = await bot.attack(target); if (r && r.success) hit.push(target.name); } catch(e){ console.log('atk', e.message); }
    await sdk.waitForTicks(1);
  } else if (wi < waypoints.length) {
    const wp = waypoints[wi];
    const d = Math.max(Math.abs(st.player.worldX-wp[0]), Math.abs(st.player.worldZ-wp[1]));
